import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
// Block tile sizes for output (M x N) and reduction dimension (K)
#define BM 64
#define BN 64
#define BK 16
// Each thread computes a TM x TN sub-tile of the output
#define TM 4
#define TN 4
// Thread block is (BN/TN) x (BM/TM) = 16 x 16 = 256 threads
#define THREADS_X (BN / TN)
#define THREADS_Y (BM / TM)
__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    int br = blockIdx.y; // block row index (in BM units)
    int bc = blockIdx.x; // block col index (in BN units)
    // Blocks entirely below the diagonal contribute zero to the result.
    if (bc * BN < br * BM) {
        int rowBase = br * BM + threadIdx.y * TM;
        int colBase = bc * BN + threadIdx.x * TN;
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int row = rowBase + i;
            if (row >= N) continue;
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int col = colBase + j;
                if (col < N) C[row * N + col] = 0.0f;
            }
        }
        return;
    }
    __shared__ float As[2][BM][BK];
    __shared__ float Bs[2][BK][BN];
    int tid = threadIdx.y * THREADS_X + threadIdx.x;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            acc[i][j] = 0.0f;
    // Restrict k-tile range using triangular structure:
    // A upper-triangular => A[row,k]=0 for k<row, so k must be >= br*BM
    // B upper-triangular => B[k,col]=0 for k>col, so k must be <= (bc+1)*BN - 1
    int t_start = (br * BM) / BK;
    int t_end = ((bc + 1) * BN - 1) / BK;
    // Prefetch first tile into buffer 0 (software pipelined double buffering)
    {
        int t = t_start;
        int rowA = tid / 4;
        int colGroupA = tid % 4;
        int colBaseA = colGroupA * 4;
        int gRowA = br * BM + rowA;
        int gColBaseA = t * BK + colBaseA;
        if (gRowA < N && gColBaseA + 3 < N) {
            float4 v = *reinterpret_cast<const float4*>(&A[gRowA * N + gColBaseA]);
            As[0][rowA][colBaseA + 0] = v.x;
            As[0][rowA][colBaseA + 1] = v.y;
            As[0][rowA][colBaseA + 2] = v.z;
            As[0][rowA][colBaseA + 3] = v.w;
        } else {
            #pragma unroll
            for (int k = 0; k < 4; ++k) {
                int gCol = gColBaseA + k;
                As[0][rowA][colBaseA + k] = (gRowA < N && gCol < N) ? A[gRowA * N + gCol] : 0.0f;
            }
        }
        int rowB = tid / 16;
        int colGroupB = tid % 16;
        int colBaseB = colGroupB * 4;
        int gRowB = t * BK + rowB;
        int gColBaseB = bc * BN + colBaseB;
        if (gRowB < N && gColBaseB + 3 < N) {
            float4 v = *reinterpret_cast<const float4*>(&B[gRowB * N + gColBaseB]);
            Bs[0][rowB][colBaseB + 0] = v.x;
            Bs[0][rowB][colBaseB + 1] = v.y;
            Bs[0][rowB][colBaseB + 2] = v.z;
            Bs[0][rowB][colBaseB + 3] = v.w;
        } else {
            #pragma unroll
            for (int k = 0; k < 4; ++k) {
                int gCol = gColBaseB + k;
                Bs[0][rowB][colBaseB + k] = (gRowB < N && gCol < N) ? B[gRowB * N + gCol] : 0.0f;
            }
        }
    }
    __syncthreads();
    int buf = 0;
    for (int t = t_start; t <= t_end; ++t) {
        int nbuf = buf ^ 1;
        if (t + 1 <= t_end) {
            int tn = t + 1;
            int rowA = tid / 4;
            int colGroupA = tid % 4;
            int colBaseA = colGroupA * 4;
            int gRowA = br * BM + rowA;
            int gColBaseA = tn * BK + colBaseA;
            if (gRowA < N && gColBaseA + 3 < N) {
                float4 v = *reinterpret_cast<const float4*>(&A[gRowA * N + gColBaseA]);
                As[nbuf][rowA][colBaseA + 0] = v.x;
                As[nbuf][rowA][colBaseA + 1] = v.y;
                As[nbuf][rowA][colBaseA + 2] = v.z;
                As[nbuf][rowA][colBaseA + 3] = v.w;
            } else {
                #pragma unroll
                for (int k = 0; k < 4; ++k) {
                    int gCol = gColBaseA + k;
                    As[nbuf][rowA][colBaseA + k] = (gRowA < N && gCol < N) ? A[gRowA * N + gCol] : 0.0f;
                }
            }
            int rowB = tid / 16;
            int colGroupB = tid % 16;
            int colBaseB = colGroupB * 4;
            int gRowB = tn * BK + rowB;
            int gColBaseB = bc * BN + colBaseB;
            if (gRowB < N && gColBaseB + 3 < N) {
                float4 v = *reinterpret_cast<const float4*>(&B[gRowB * N + gColBaseB]);
                Bs[nbuf][rowB][colBaseB + 0] = v.x;
                Bs[nbuf][rowB][colBaseB + 1] = v.y;
                Bs[nbuf][rowB][colBaseB + 2] = v.z;
                Bs[nbuf][rowB][colBaseB + 3] = v.w;
            } else {
                #pragma unroll
                for (int k = 0; k < 4; ++k) {
                    int gCol = gColBaseB + k;
                    Bs[nbuf][rowB][colBaseB + k] = (gRowB < N && gCol < N) ? B[gRowB * N + gCol] : 0.0f;
                }
            }
        }
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float a_reg[TM];
            float b_reg[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                a_reg[i] = As[buf][threadIdx.y * TM + i][kk];
            }
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                b_reg[j] = Bs[buf][kk][threadIdx.x * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        __syncthreads();
        buf = nbuf;
    }
    int rowBase = br * BM + threadIdx.y * TM;
    int colBase = bc * BN + threadIdx.x * TN;
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int row = rowBase + i;
        if (row >= N) continue;
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            int col = colBase + j;
            if (col < N) {
                C[row * N + col] = (row <= col) ? acc[i][j] : 0.0f;
            }
        }
    }
}
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have same size");
    A = A.contiguous();
    B = B.contiguous();
    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());
    dim3 block(THREADS_X, THREADS_Y);
    dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );
    return C;
}
"""

cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul = load_inline(
    name="triu_matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for
    upper triangular matrices using a custom fused CUDA kernel that
    exploits the triangular sparsity structure and fuses the triu masking
    directly into the matmul computation.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return triu_matmul.triu_matmul_cuda(A, B)


N = 4096

def get_inputs():
    A = torch.triu(torch.rand(N, N))
    B = torch.triu(torch.rand(N, N))
    return [A.cuda(), B.cuda()]

def get_init_inputs():
    return []

